// 2 - Pull every record and bill in the case's Google Drive folder, page by page.
// One item per document goes out, so Claude reads one document at a time and every
// fact keeps its file name and page number.
// Needs pdfjs-dist allowed on your self-hosted n8n (NODE_FUNCTION_ALLOW_EXTERNAL=pdfjs-dist).
const pdfjs = require('pdfjs-dist/legacy/build/pdf.js');
const caseFile = $('1 - Case Marked Ready for Demand in Your Case System').first().json.body;
const auth = 'googleDriveOAuth2Api';

const list = await this.helpers.httpRequestWithAuthentication.call(this, auth, {
  method: 'GET',
  url: 'https://www.googleapis.com/drive/v3/files',
  qs: {
    q: "'" + caseFile.drive_folder_id + "' in parents and mimeType = 'application/pdf' and trashed = false",
    fields: 'files(id,name,createdTime)',
    pageSize: 200,
  },
});

const out = [];
for (const f of list.files || []) {
  const bytes = await this.helpers.httpRequestWithAuthentication.call(this, auth, {
    method: 'GET',
    url: 'https://www.googleapis.com/drive/v3/files/' + f.id + '?alt=media',
    encoding: 'arraybuffer',
    json: false,
  });
  const pdf = await pdfjs.getDocument({ data: new Uint8Array(bytes) }).promise;
  const pages = [];
  const unreadable = [];
  for (let p = 1; p <= pdf.numPages; p++) {
    const content = await (await pdf.getPage(p)).getTextContent();
    const text = content.items.map(i => i.str).join(' ').replace(/\s+/g, ' ').trim();
    if (text.length < 20) unreadable.push(p); // scanned fax page: goes to OCR, never skipped silently
    pages.push({ page: p, text });
  }
  out.push({ json: {
    case_id: caseFile.case_id,
    file_id: f.id,
    file_name: f.name,
    page_count: pdf.numPages,
    unreadable_pages: unreadable,
    pages_text: pages.map(pg => '[PAGE ' + pg.page + ']\n' + pg.text).join('\n\n'),
  }});
}
if (!out.length) throw new Error('No PDF records found in the Drive folder for case ' + caseFile.case_id);
return out;

