// 4 - Total medical expenses by provider and flag what is missing before anyone drafts.
// Pure arithmetic and checks on Claude's extracted entries: no model does the math.
const caseFile = $('1 - Case Marked Ready for Demand in Your Case System').first().json.body;
const cfg = $('0 - Config: Your Settings').first().json;
const gapDays = Number(cfg.treatment_gap_days);
if (!gapDays) throw new Error('Set treatment_gap_days in 0 - Config: Your Settings');

const docs = $input.all().map(i => i.json.output);
const entries = docs.flatMap(d => (d.entries || []).map(e => ({ ...e, document_type: d.document_type })));

// Expenses by provider, each line keeping its source file and page.
const byProvider = {};
for (const e of entries.filter(x => x.charge_usd != null)) {
  const p = byProvider[e.provider] || (byProvider[e.provider] = { provider: e.provider, total_usd: 0, first_visit: e.date_of_service, last_visit: e.date_of_service, lines: [] });
  p.total_usd = Math.round((p.total_usd + Number(e.charge_usd)) * 100) / 100;
  if (e.date_of_service < p.first_visit) p.first_visit = e.date_of_service;
  if (e.date_of_service > p.last_visit) p.last_visit = e.date_of_service;
  p.lines.push({ date: e.date_of_service, description: e.description, charge_usd: e.charge_usd, source: e.source_file + ', p. ' + e.source_page });
}
const providers = Object.values(byProvider);
const total = Math.round(providers.reduce((s, p) => s + p.total_usd, 0) * 100) / 100;

// Chronology across all providers.
const chronology = entries.slice().sort((a, b) => String(a.date_of_service || '').localeCompare(String(b.date_of_service || '')));

// What is missing.
const flags = [];
const recordProviders = new Set(entries.filter(e => e.document_type === 'medical_record').map(e => e.provider));
const billProviders = new Set(entries.filter(e => e.document_type === 'bill').map(e => e.provider));
for (const name of caseFile.providers_on_file || []) {
  if (!recordProviders.has(name)) flags.push({ type: 'missing_records', provider: name, detail: 'Provider is on the case but no treatment records are in the folder.' });
  if (!billProviders.has(name)) flags.push({ type: 'missing_bill', provider: name, detail: 'Provider is on the case but no bill or ledger is in the folder.' });
}
const dates = [...new Set(chronology.map(e => e.date_of_service).filter(Boolean))];
for (let i = 1; i < dates.length; i++) {
  const days = Math.round((new Date(dates[i]) - new Date(dates[i - 1])) / 86400000);
  if (days > gapDays) flags.push({ type: 'treatment_gap', from: dates[i - 1], to: dates[i], days, detail: 'No treatment for ' + days + ' days. Attorney to review before the demand goes out.' });
}
for (const d of docs) {
  if ((d.unreadable_pages || []).length) flags.push({ type: 'unreadable_pages', file: d.file_name, pages: d.unreadable_pages, detail: 'Scanned pages with no readable text. Run OCR before finalizing.' });
  for (const g of d.missing_or_incomplete || []) flags.push({ type: 'incomplete_document', file: d.file_name, detail: g });
}

// Exhibit index: one exhibit per source document, in treatment order.
const exhibits = docs
  .slice()
  .sort((a, b) => String(a.first_date || '').localeCompare(String(b.first_date || '')))
  .map((d, i) => ({ exhibit: String.fromCharCode(65 + i), file_name: d.file_name, file_id: d.file_id, description: d.document_title, pages: d.page_count }));

return [{ json: { case_id: caseFile.case_id, client_name: caseFile.client_name, incident_date: caseFile.incident_date, total_medical_expenses_usd: total, providers, chronology, flags, exhibits, case_manager_email: caseFile.case_manager_email, assigned_attorney_email: caseFile.assigned_attorney_email, drive_folder_id: caseFile.drive_folder_id } }];

