// 6 - Copy your firm's demand template into the case folder, then fill it.
// The draft stays an editable Google Doc; every version is a new copy, so edits never overwrite history.
const cfg = $('0 - Config: Your Settings').first().json;
const facts = $('4 - Total Medical Expenses by Provider, Flag Gaps and Missing Records').first().json;
// Claude returns the draft as JSON (letter_body, treatment_chronology, medical_specials, open_items_for_attorney).
const raw = $input.first().json;
const draft = raw.output || JSON.parse(String(raw.text).replace(/^```(json)?|```$/g, '').trim());
const asText = v => Array.isArray(v) ? v.map(x => typeof x === 'string' ? x : JSON.stringify(x)).join('\n') : String(v || '');
const auth = 'googleDocsOAuth2Api';
const version = $('7 - Gmail: Attorney Approves or Sends Edits Back').isExecuted ? $('7 - Gmail: Attorney Approves or Sends Edits Back').all().length + 1 : 1;

const copy = await this.helpers.httpRequestWithAuthentication.call(this, 'googleDriveOAuth2Api', {
  method: 'POST',
  url: 'https://www.googleapis.com/drive/v3/files/' + cfg.demand_template_doc_id + '/copy',
  body: { name: 'Demand - ' + facts.client_name + ' - ' + facts.case_id + ' - DRAFT v' + version, parents: [facts.drive_folder_id] },
  json: true,
});

const exhibitIndex = facts.exhibits.map(x => 'Exhibit ' + x.exhibit + ' - ' + x.description + ' (' + x.file_name + ', ' + x.pages + ' pages)').join('\n');
const fill = {
  '{{CLIENT_NAME}}': facts.client_name,
  '{{CLAIM_NUMBER}}': $('1 - Case Marked Ready for Demand in Your Case System').first().json.body.claim_number,
  '{{INSURER}}': $('1 - Case Marked Ready for Demand in Your Case System').first().json.body.insurer,
  '{{DEMAND_BODY}}': draft.letter_body,
  '{{TREATMENT_CHRONOLOGY}}': asText(draft.treatment_chronology),
  '{{MEDICAL_SPECIALS_TABLE}}': asText(draft.medical_specials),
  '{{EXHIBIT_INDEX}}': exhibitIndex,
  '{{OPEN_ITEMS}}': asText(draft.open_items_for_attorney),
};
await this.helpers.httpRequestWithAuthentication.call(this, auth, {
  method: 'POST',
  url: 'https://docs.googleapis.com/v1/documents/' + copy.id + ':batchUpdate',
  body: { requests: Object.entries(fill).map(([tag, text]) => ({ replaceAllText: { containsText: { text: tag, matchCase: true }, replaceText: String(text || '') } })) },
  json: true,
});

return [{ json: { case_id: facts.case_id, client_name: facts.client_name, version, doc_id: copy.id, doc_url: 'https://docs.google.com/document/d/' + copy.id + '/edit', total_medical_expenses_usd: facts.total_medical_expenses_usd, flags: facts.flags, exhibit_count: facts.exhibits.length, attorney_email: facts.assigned_attorney_email } }];

