// 9 - Export the approved demand package as Word and PDF into the case folder.
// The Google Doc stays as the editable master; the two files are what goes to the adjuster.
const doc = $('6 - Google Docs: Save the Draft With the Exhibit Index').last().json;
const folder = $('4 - Total Medical Expenses by Provider, Flag Gaps and Missing Records').first().json.drive_folder_id;
const formats = [
  { ext: 'docx', mime: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document' },
  { ext: 'pdf', mime: 'application/pdf' },
];
const saved = [];
for (const f of formats) {
  const bytes = Buffer.from(await this.helpers.httpRequestWithAuthentication.call(this, 'googleDriveOAuth2Api', {
    method: 'GET',
    url: 'https://www.googleapis.com/drive/v3/files/' + doc.doc_id + '/export',
    qs: { mimeType: f.mime },
    encoding: 'arraybuffer',
    json: false,
  }));
  const name = 'Demand - ' + doc.client_name + ' - ' + doc.case_id + ' - APPROVED.' + f.ext;
  const boundary = 'demand' + Date.now();
  const body = Buffer.concat([
    Buffer.from('--' + boundary + '\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n' + JSON.stringify({ name, parents: [folder] }) + '\r\n--' + boundary + '\r\nContent-Type: ' + f.mime + '\r\n\r\n'),
    bytes,
    Buffer.from('\r\n--' + boundary + '--'),
  ]);
  const file = await this.helpers.httpRequestWithAuthentication.call(this, 'googleDriveOAuth2Api', {
    method: 'POST',
    url: 'https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart&fields=id,name,webViewLink',
    headers: { 'Content-Type': 'multipart/related; boundary=' + boundary },
    body,
    json: false,
  });
  saved.push(JSON.parse(file));
}
return [{ json: { case_id: doc.case_id, status: 'Demand approved', approved_version: doc.version, google_doc: doc.doc_url, word_file: saved[0].webViewLink, pdf_file: saved[1].webViewLink } }];

